#include <stdio.h>
int main(){
    int arr[3][3] = {{1,2,3},{4,5,6},{7,8,9}};
    int sum = 0;
    for (int i = 0; i < 3; i++) {
        sum += *(*(arr+i)+i);
    }
    printf("%d\n", sum);
}

class A {
    protected int x = 100;
    public void show(){
        System.out.println("A:" + x);
    }
}
class B extends A {
    protected int x = 200;
    public void show(){
        super.show();
        System.out.println("B:" + x);
        System.out.println("B:" + super.x);
    }
}
public class Main {
    public static void main(String[] args){
        B obj = new B();
        obj.show();
    }
}
